import{_ as e,o as a,c as o,ag as i}from"./chunks/framework.CxkNbRKf.js";const s="/nada-documentation/images/image197.png",n="/nada-documentation/images/image198.png",d="/nada-documentation/images/image199.png",r="/nada-documentation/images/image200.png",p="/nada-documentation/images/image201.png",l="/nada-documentation/images/image202.png",c="/nada-documentation/images/image203.png",h="/nada-documentation/images/image204.png",m="/nada-documentation/images/image205.png",g="/nada-documentation/images/image206.png",u="/nada-documentation/images/image207.png",f="/nada-documentation/images/image208.png",b="/nada-documentation/images/image209.png",y="/nada-documentation/images/image210.png",w="/nada-documentation/images/image211.png",v="/nada-documentation/images/image212.png",_="/nada-documentation/images/image213.png",j="/nada-documentation/images/image214.png",T="/nada-documentation/images/image215.png",D="/nada-documentation/images/image216.png",k="/nada-documentation/images/image217.png",x="/nada-documentation/images/image218.png",q="/nada-documentation/images/image219.png",A="/nada-documentation/images/image220.png",P="/nada-documentation/images/image221.png",S="/nada-documentation/images/image222.png",z=JSON.parse('{"title":"Data deposit system","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/data-deposit.md","filePath":"admin-guide/web-ui/data-deposit.md","lastUpdated":1786379412000}'),C={name:"admin-guide/web-ui/data-deposit.md"};function I(N,t,F,E,R,O){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="data-deposit-system" tabindex="-1">Data deposit system <a class="header-anchor" href="#data-deposit-system" aria-label="Permalink to &quot;Data deposit system&quot;">​</a></h1><p>The NADA Data Deposit system is an optional component of the application, which needs to be installed and activated separately from the main application. It is intended to allow catalog administrators to collect datasets from authenticated/authorized contributors. The current version of the Data Deposit applies to microdata only. Future versions of NADA will accommodate additional data types.  When the Data Deposit is installed, a new item can be added to the main menu linking to a landing page (to be developed by the catalog administrator). This landing page should provide some information to data depositors on what to deposit, and how, and a link to the Data Deposit application itself.</p><p><img src="'+s+'" alt=""></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Data Deposit system allows contributors to a data catalog to submit datasets for publishing in the catalog. It does not automatically publish or add content to the catalog; it is used to collect data, metadata, and resources related to a dataset and transfer these materials to a catalog&#39;s curation team. Typically, a Data Deposit system will be implemented within an organization, on an intranet or controlled-access server. For security reasons, the Data deposit should not be used as a crowd-sourcing data gathering system.</p><p>The Data Deposit allows contributors to upload files, enter metadata using templates, and provide instructions to the data curators. It logs all activities, providing full traceability of the data acquisition process. It informs depositors of their actions, providing confirmation and evidence of data deposit when needed. It allows data curators to organize the data curation work. The use of metadata templates reduces the burden on data curators (when depositors enter detailed metadata); it is however a system that minimizes the burden on data depositors. All metadata is exportable to DDI 2.5</p><p><img src="'+n+'" alt=""></p><h2 id="installation-and-activation" tabindex="-1">Installation and activation <a class="header-anchor" href="#installation-and-activation" aria-label="Permalink to &quot;Installation and activation&quot;">​</a></h2><p>NADA includes the data deposit as of V5.0.4. However, it is not installed by default and must be installed and enabled manually.</p><h3 id="create-database-tables" tabindex="-1">Create database tables <a class="header-anchor" href="#create-database-tables" aria-label="Permalink to &quot;Create database tables&quot;">​</a></h3><p>Run the SQL from the file <code>install/schema.dd.mysql.sql</code> on your NADA database. This will create all the tables used by the data deposit.</p><h3 id="enable-data-deposit" tabindex="-1">Enable data deposit <a class="header-anchor" href="#enable-data-deposit" aria-label="Permalink to &quot;Enable data deposit&quot;">​</a></h3><ul><li>To enable data deposit, edit the configuration file <code>application/config/datadeposit.php</code>.</li><li>Change the setting <code>enable_datadeposit</code> to <code>TRUE</code>:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  $config[&#39;datadeposit&#39;][&#39;enable_datadeposit&#39;] = TRUE;</span></span></code></pre></div><ul><li>Save the file.</li><li>Open web browser and navigate to <code>https://your-nada-website/index.php/datadeposit</code> to see data deposit frontend.</li></ul><h2 id="use-by-data-depositors" tabindex="-1">Use by data depositors <a class="header-anchor" href="#use-by-data-depositors" aria-label="Permalink to &quot;Use by data depositors&quot;">​</a></h2><p>The deposit application landing page displays information about the catalog; deposit instructions and guidance for depositors to help them prepare their data and documentation before they initiate the deposit process, as well as what to expect once a deposit is submitted. Once a contributor is ready to deposit, the first step is to click the Deposit Data button. This prompts the contributor to log in to the application.</p><p><img src="'+d+'" alt=""> Once a depositor logs in to the deposit application, the first page they see is titled <strong>My projects.</strong> This page lists all deposit projects initiated and submitted by the individual who is logged in, as well as deposit projects where the individual is included as a collaborator. From this page, a depositor can create new deposit projects, review existing projects and monitor the status for each project in their list.</p><p>Deposit status can take any of the following values:</p><ul><li><p><strong>Draft</strong>: The depositor or named collaborators can edit, upload resources for any length of time until they are ready to submit, or they can delete the deposit project.</p></li><li><p><strong>Submitted:</strong> This status is displayed when deposit project has been submitted. The depositor cannot edit or delete the project, but they can request the administrator to reopen the project if they need to add any resources or edit the deposit form.</p></li><li><p><strong>Accepted</strong>: The deposit form has been reviewed by the administrator, the data and metadata have been transferred to the curators for processing. At this point, the depositor or any named collaborators cannot edit the request. If they need any changes made to the project, they will need to request the administrator to reopen the project (return it to draft status) on their behalf.</p></li><li><p><strong>Processed</strong>: deposit is processed i.e., data and metadata are curated and if authorized for publication, the metadata and data are published in the catalog.</p></li><li><p><strong>Closed</strong></p></li></ul><h2 id="creating-a-new-deposit-project" tabindex="-1">Creating a new deposit project <a class="header-anchor" href="#creating-a-new-deposit-project" aria-label="Permalink to &quot;Creating a new deposit project&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><h2 id="project-information" tabindex="-1">Project information <a class="header-anchor" href="#project-information" aria-label="Permalink to &quot;Project information&quot;">​</a></h2><p>The <strong>Create New Project</strong> button launches a form for the depositor to enter basic deposit project information i.e., title, abbreviation and description. The depositor can also specify email addresses of any collaborators on the project who would also have view and edit rights to the project. Collaboration and project description details are optional, but the title and project short name are mandatory.</p><p><img src="'+p+'" alt=""></p><p>Once this section is saved, a draft deposit project is created in the system, assigned a unique project id, and listed under the specified project title. On My Projects page, the project is listed with Edit, (View) Summary, and Delete options available for the depositor.</p><p><img src="'+l+'" alt=""></p><p>When editing the project, you will notice that there are additional tabs available, and the project information is now displayed on the first tab - the Project Information Tab.</p><p><img src="'+c+'" alt=""></p><h2 id="study-description" tabindex="-1">Study Description <a class="header-anchor" href="#study-description" aria-label="Permalink to &quot;Study Description&quot;">​</a></h2><p>Click the <strong>Study Description</strong> tab to provide Study Description details. The current version of the data deposit application accepts microdata, so the deposit form fields correspond to DDI metadata fields, which is the international metadata standard for microdata.</p><p><img src="'+h+'" alt=""></p><p>There are a few functions available to aid the deposit process. The depositor can adjust form settings, import metadata from another project, expand/collapse all form fields.</p><h2 id="adjustable-form-settings" tabindex="-1">Adjustable form settings <a class="header-anchor" href="#adjustable-form-settings" aria-label="Permalink to &quot;Adjustable form settings&quot;">​</a></h2><p>By default, the study description form displays all the form fields. However, the depositor can customize the form settings to hide/display help (descriptions for each field including examples) or show only recommended fields, or mandatory fields.</p><p><img src="'+m+'" alt=""></p><p><em><strong>Show field help</strong></em></p><p><img src="'+g+'" alt=""></p><p><em><strong>Show Recommended Fields</strong></em></p><p><img src="'+u+'" alt=""></p><p><em><strong>Show Mandatory Fields</strong></em></p><p><img src="'+f+'" alt=""></p><h2 id="metadata-import" tabindex="-1">Metadata Import <a class="header-anchor" href="#metadata-import" aria-label="Permalink to &quot;Metadata Import&quot;">​</a></h2><p>If a new project has a study description similar to an existing project, the deposit application allows depositors to import metadata from a project in their projects list, to avoid manually filling all the form fields, and then edit as needed. To import, click the <strong>Import Metadata</strong> button then select the relevant project to import from.</p><p><img src="'+b+'" alt=""></p><h2 id="form-display-options-expand-all-collapse-all" tabindex="-1">Form display options: Expand All/Collapse All <a class="header-anchor" href="#form-display-options-expand-all-collapse-all" aria-label="Permalink to &quot;Form display options: Expand All/Collapse All&quot;">​</a></h2><p>By default, the form is set to collapse all fields. Depending on preference, the depositor can set the form to expand all fields or collapse all fields by clicking on the relevant button. &#39;Expand all&#39; reveals all the form fields in each section. Collapse All hides the form fields, and shows only the section titles to give the user an overall view of the sections in the form.</p><p>The <strong>Save</strong> button is at the bottom of the Study Description form saves the Study Description update to the deposit project. The deposit remains in draft status and the project can be edited (or deleted) anytime until it is submitted. Any pending tasks e.g mandatory fields that need to be filled will be indicated in the <strong>Pending Tasks</strong> section to the left of the form. Completed tasks are indicated by a green check mark.</p><h2 id="file-upload" tabindex="-1">File Upload <a class="header-anchor" href="#file-upload" aria-label="Permalink to &quot;File Upload&quot;">​</a></h2><p>Data Files and resources are uploaded from the <strong>Data files and other Resources</strong> tab**.**</p><p><img src="'+y+'" alt=""></p><p>The depositor can either drag and drop multiple files of up to 2G B and click <strong>Start Upload</strong>, or click <strong>Add Files</strong>, navigate to the file location to select files then click <strong>Start Upload</strong>. Allowed file types are indicated in the above screenshot (jpg, jpeg, gif, png, zip, doc, docx, pdf, sav, dta, txt, xls, xlsx, ppt, csv, rar, do, r, mp4, dbf, sps). Uploaded files are listed in a table showing the file name, type and size. This helps the depositor review the uploads and make sure the correct files have been uploaded.</p><p>The depositor can update the files in the project by deleting or uploading new files. A depositor can either delete individual files from the Actions column, or through batch delete i.e., checking relevant file names and selecting Delete from the batch actions dropdown menu then clicking Apply. To upload new files, click the Upload button above the top right corner of the table.</p><p><img src="'+w+'" alt=""></p><p>Depositors have the option to define the file or document type when uploading resources. This is done via the Edit link. This step is optional for the depositor as file type can also be defined during curation.</p><p><img src="'+v+'" alt=""></p><p>Now in place of N/A, the Type column will reflect the file type as defined by the depositor. The total file count is displayed under Pending Tasks and on the bottom right corner of the table.</p><p><img src="'+_+'" alt=""></p><h2 id="citations-optional" tabindex="-1">Citations (optional) <a class="header-anchor" href="#citations-optional" aria-label="Permalink to &quot;Citations (optional)&quot;">​</a></h2><p>The <strong>Citations</strong> tab is optional and is used to enter details of any publications that have used the data being deposited.</p><p><img src="'+j+'" alt=""></p><p>To add a citation, click the <strong>Add New Citation</strong> button to launch the citations form.</p><p><img src="'+T+'" alt=""></p><p>Once all the details are added and submitted, the new citation will be listed under the citations tab with options to edit or delete it and add another citation. The number of citations added to the project is also listed under Pending Tasks. To add another citation, click the <strong>Add New Citation</strong> button and follow the same process.</p><p><img src="'+D+'" alt=""></p><h2 id="deposit-review-and-submit" tabindex="-1">Deposit Review and Submit <a class="header-anchor" href="#deposit-review-and-submit" aria-label="Permalink to &quot;Deposit Review and Submit&quot;">​</a></h2><p>The Review and Submit tab has two sub-menus, a Review tab and a Submit tab. The default view is the Review tab which presents all the project details, study description, files and citations for review.</p><p>From this tab, the depositor can generate a DDI xml file and a resource description file (RDF) -- exporting the metadata to machine readable format that can be read by software including NADA; a print preview (summary of the deposit); or email the deposit information to others for review. These options are available on the top right above the project information box.</p><p><img src="'+k+'" alt=""></p><p><img src="'+x+'" alt=""></p><p><img src="'+q+'" alt=""></p><p>Once all the deposit information is reviewed and found to be satisfactory, it is ready for submission. Project submission is done from the Submit sub-menu.</p><p><img src="'+A+'" alt=""></p><p>This presents a form where the depositor specifies</p><ul><li><p><strong>Access policy</strong> suitable for the data, in line with the data terms of use</p></li><li><p><strong>Catalog to publish</strong> -- if there are multiple catalogs</p></li><li><p><strong>Embargo information</strong> - If the dataset is embargoed, the depositor indicates the terms of the embargo e.g., time-period and any other special instructions.</p></li><li><p><strong>Disclosure risk</strong> - Safeguarding the identity and privacy of respondents that have provided the data is important. The depositor can specify any identifying variables in the data (e.g., names, official ID numbers, precise GIS coordinates, etc, or any variables deemed otherwise sensitive in the study setting (e.g., ethnicity, tribe, religion, etc) so they can be treated before the data is distributed. Ideally these would be treated before the data is deposited.</p></li><li><p><strong>Key variables</strong></p></li><li><p><strong>Notes to the library</strong></p></li><li><p><strong>cc</strong> -- email addresses of additional people who will also receive a summary of the deposit submission.</p></li></ul><p>Once this information is submitted, the depositor is given opportunity to confirm submission with the understanding that they will not be able to edit the deposit once it is submitted. Clicking the <strong>Submit</strong> button will submit the deposit. The depositor receives a confirmation email of the deposit.</p><p><img src="'+P+'" alt=""></p><p>The updated status of the deposit is reflected on <strong>My Projects</strong> page, and a summary of the deposit can be viewed by clicking on the project title. At this point the project cannot be edited or deleted. If any updates need to be made to the project after submission, the depositor needs to contact the administrator to request the project to be re-opened.</p><p><img src="'+S+'" alt=""></p><p>The status of the deposit will as change as the deposit goes through the curation workflow. It will be updated to reflect the current status of the deposit.</p>',80)])])}const M=e(C,[["render",I]]);export{z as __pageData,M as default};
